<script setup>
defineProps({ trials: Array });
const date = value => new Date(`${String(value).slice(0,10)}T12:00:00`).toLocaleDateString('fr-CH');
const money = value => Number(value || 0).toLocaleString('fr-CH', { minimumFractionDigits: 2 });
</script>
<template><section class="overflow-hidden rounded-3xl bg-white"><div class="border-b border-black/5 px-6 py-5"><h2 class="font-serif text-2xl">Demandes de cours d’essai</h2><p class="mt-1 text-xs text-black/45">{{ trials.length }} demandes à traiter</p></div><div v-if="trials.length" class="overflow-x-auto"><table class="w-full min-w-[950px] text-left"><thead class="bg-[#f7f5f0] text-[11px] font-bold uppercase tracking-wider text-black/45"><tr><th class="px-6 py-4">Élève</th><th class="px-5 py-4">Cours</th><th class="px-5 py-4">Date souhaitée</th><th class="px-5 py-4">Rôle</th><th class="px-5 py-4">Tarif</th><th class="px-6 py-4 text-right">Action</th></tr></thead><tbody class="divide-y divide-black/5"><tr v-for="trial in trials" :key="trial.id" class="hover:bg-[#faf9f6]"><td class="px-6 py-5"><strong>{{ trial.first_name }} {{ trial.last_name }}</strong><a :href="`mailto:${trial.email}`" class="mt-1 block text-xs text-black/40">{{ trial.email }}</a><a :href="`tel:${trial.phone}`" class="text-xs text-black/40">{{ trial.phone }}</a></td><td class="px-5 py-5"><strong>{{ trial.course?.title }}</strong><p v-if="trial.message" class="mt-1 max-w-xs truncate text-xs italic text-black/40">« {{ trial.message }} »</p></td><td class="px-5 py-5">{{ date(trial.preferred_date) }}<p class="text-xs text-black/40">{{ trial.course?.time }}</p></td><td class="px-5 py-5"><span class="rounded-full bg-purple-50 px-3 py-1 text-xs font-bold uppercase text-purple-700">{{ trial.dance_role || '—' }}</span></td><td class="px-5 py-5"><span class="font-bold" :class="trial.trial_is_free ? 'text-green-700' : 'text-amber-700'">{{ trial.trial_is_free ? 'Gratuit' : `${money(trial.trial_price)} CHF` }}</span></td><td class="px-6 py-5 text-right"><a :href="`mailto:${trial.email}?subject=Cours d'essai ${trial.course?.title}`" class="inline-block rounded-full bg-ink px-4 py-2 text-xs font-bold text-white">Contacter</a></td></tr></tbody></table></div><div v-else class="px-6 py-16 text-center text-black/40">Aucune demande d’essai.</div></section></template>
